#!/usr/bin/env sh
# Run against a disposable HookScope database only.  Results are generated by
# autocannon and retained locally under load-test-results/ (which is ignored).
set -eu

base_url="${HOOKSCOPE_URL:-http://127.0.0.1:3000}"
endpoint_id="${1:?Usage: HOOKSCOPE_URL=http://127.0.0.1:3000 scripts/load-test.sh ENDPOINT_ID}"
mkdir -p load-test-results
payload='{"event":"load-test","source":"autocannon"}'

npx --yes autocannon -m POST -c 10 -d 15 -H 'content-type: application/json' -b "$payload" \
  --json "$base_url/h/$endpoint_id" > load-test-results/baseline.json
npx --yes autocannon -m POST -c 50 -d 15 -H 'content-type: application/json' -b "$payload" \
  --json "$base_url/h/$endpoint_id" > load-test-results/high-concurrency.json

echo "Wrote load-test-results/baseline.json and high-concurrency.json"
